import {paymentPdf} from './payment-pdf.js?v=20261004';
import {copyMessage} from './clipboard.js';
export function initSalesSearch({call,checkSeller,context}){
 const $=id=>document.getElementById(id);let rows=[],cursor=null,phone='',generation=0,busy=false;
 async function search(reset){if(busy||!checkSeller())return;busy=true;const stamp=++generation;if(reset){phone=$('sales-search-phone').value.trim();rows=[];cursor=null;} $('sales-search-button').disabled=true;$('sales-search-more').disabled=true;$('sales-search-state').textContent='Buscando ventas…';
 try{const {data}=await call('searchSales',{...context(),phone,cursor:reset?null:cursor});if(stamp!==generation)return;rows=reset?data.rows:[...rows,...data.rows];cursor=data.next;render();$('sales-search-state').textContent=rows.length?`${rows.length} ventas encontradas.`:'No hay ventas para este teléfono.';}
 catch{$('sales-search-state').textContent='No se pudo buscar. Revisa el teléfono y vuelve a intentarlo.';}finally{busy=false;$('sales-search-button').disabled=false;$('sales-search-more').disabled=false;}}
 function render(){const list=$('sales-search-results');list.replaceChildren();for(const sale of rows){const card=document.createElement('article');card.className='quote-card';const title=document.createElement('h3'),info=document.createElement('p'),state=document.createElement('p'),pdf=document.createElement('button'),copy=document.createElement('button'),code=document.createElement('input');title.textContent=sale.product;info.textContent=`+${sale.customerPhone} · ${new Intl.DateTimeFormat('es-CR',{timeZone:'America/Costa_Rica',dateStyle:'short'}).format(new Date(sale.createdAt))} · ${sale.status==='cancelled'?'Cancelada':sale.status==='pending'?'Por aprobar':'Aprobada'}`;pdf.textContent='Descargar comprobante PDF';copy.textContent='Copiar código de seguimiento';for(const b of [pdf,copy]){b.type='button';b.className='button';}code.readOnly=true;code.hidden=true;code.setAttribute('aria-label','Código de seguimiento');state.setAttribute('role','status');let data;
 async function action(mode){if(!checkSeller())return;pdf.disabled=copy.disabled=true;state.textContent='Preparando…';try{data=(await call('saleDocuments',{...context(),phone:sale.customerPhone,saleId:sale.saleId})).data;code.value=data.trackingCode;code.hidden=false;if(mode==='copy'){try{await copyMessage(data.trackingCode);state.textContent='Código copiado. El cliente puede usarlo en pitstop-cbe24.web.app.';}catch{code.focus();code.select();state.textContent='Copia el código seleccionado.';}}else{const blob=await paymentPdf({...data.paymentDocument,trackingCode:data.trackingCode}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='PitStop-'+data.paymentDocument.number+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);state.textContent='PDF listo. Revisa las descargas del navegador.';}}catch{state.textContent='No se pudo recuperar esta venta. Busca nuevamente e inténtalo otra vez.';}finally{pdf.disabled=copy.disabled=false;}}
 pdf.addEventListener('click',()=>action('pdf'));copy.addEventListener('click',()=>action('copy'));card.append(title,info,pdf,copy,code,state);list.append(card);} $('sales-search-more').hidden=!cursor;}
 $('sales-search-form').addEventListener('submit',e=>{e.preventDefault();search(true);});$('sales-search-more').addEventListener('click',()=>search(false));
}
